const clean = (text) => String(text || "").replace(/\s+/g, " ").trim()
return Array.from(document.querySelectorAll("h1,h2,h3,h4"))
  .slice(0, 120)
  .map((el) => ({ level: Number(String(el.tagName).slice(1)) || 2, text: clean(el.textContent) }))
  .filter((item) => item.text)

const textOf = (el) => {
  if (!el) return ""
  const clone = el.cloneNode(true)
  clone.querySelectorAll("script,style,noscript,nav,aside,footer").forEach((n) => n.remove())
  clone.querySelectorAll("br").forEach((n) => n.replaceWith("\n"))
  clone.querySelectorAll("p,div,li,h1,h2,h3,h4,h5,h6,tr,section,article").forEach((n) => n.append("\n"))
  return String(clone.textContent || "").replace(/[ \t]+/g, " ").replace(/\n{3,}/g, "\n\n").trim()
}
let best = ""
for (const sel of ["article", "main", "[role=main]", ".post", ".article", ".content", "#content"]) {
  for (const el of Array.from(document.querySelectorAll(sel))) {
    const text = textOf(el)
    if (text.length > best.length && text.length > 200) best = text
  }
}
if (!best) best = textOf(document.body)
return best.slice(0, 12000)

// document 是页面副本：这里删什么都不会影响真实页面
const junk = [".subscribe", "#subscribe", ".newsletter", ".sidebar", "aside",
  "[class*=subscribe]", "[class*=newsletter]", "[class*=paywall]"]
for (const sel of junk) document.querySelectorAll(sel).forEach((el) => el.remove())
const textOf = (el) => String(el.textContent || "").replace(/\s+/g, " ").trim()
return Array.from(document.querySelectorAll("h1,h2,h3"))
  .map((el) => ({ level: Number(String(el.tagName).slice(1)) || 2, text: textOf(el) }))
  .filter((item) => item.text)
  .slice(0, 120)
